import type { Rep, TeamGoal, Entry, Habit, HabitCompletion, QuizQuestion, KpiKey, Kpi, PromoContent, ChatMessage, Client, StoreLocation, ServicePlan, TabletPlan, SalesPeriod } from '../types';

const INITIAL_REPS: Rep[] = [
  { id: 1, name: 'Cesar', avatar: 'C' },
