    title: 'BLACK FRIDAY: iPhone 14',
    category: 'DEVICE',
    description: 'Port-in + Veriff: $49.99 + 1mo on 5G/5G+. No Port: $149.99 + 1mo on 5G/5G+.',
    dates: '11/27 – 12/1',
    status: 'Active',
  },
  {
    id: 'promo_post_bf',
    title: 'POST-BLACK FRIDAY DEALS',
    category: 'DEVICE',
    description: 'S25 FE & Razr: $99.99 (Port) or $199.99 (No Port) + 2mo. iPhone 14: $49.99 (Port) or $149.99 (No Port) + 3mo.',
    dates: '12/2 – 1/7',
    status: 'Active',
  },
];

const INITIAL_CHAT_MESSAGES: ChatMessage[] = [];

const INITIAL_STORE_LOCATIONS: StoreLocation[] = [
    { id: 'store1', name: '2015 Mannheim Rd ' },
    { id: 'store2', name: '2743 Mannheim Rd' },
    { id: 'store3', name: '74 North Villa Park' },
];

const INITIAL_CLIENTS: Client[] = [];

const generateInitialEntries = (): Entry[] => {
    const entries: Entry[] = [];
    const today = new Date();

    // Generate for current month
    const daysInCurrentMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate();
    for (let i = 1; i <= daysInCurrentMonth; i++) {
        if (new Date(today.getFullYear(), today.getMonth(), i).getDay() % 6 !== 0) {
            for (const rep of INITIAL_REPS) {
                 if (Math.random() > 0.2) {
                    const date = new Date(today.getFullYear(), today.getMonth(), i).toISOString().split('T')[0];
                    entries.push({
                        id: `entry_${rep.id}_${date}`,
                        repId: rep.id,
                        date: date,
                        activations: Math.random() > 0.5 ? (Math.random() > 0.8 ? 2 : 1) : 0,
                        vhi: Math.random() > 0.9 ? 1 : 0,
                        tablets: Math.random() > 0.9 ? 1 : 0,
                        protect: Math.random() > 0.6 ? 1 : 0,
                        accessories: Math.floor(Math.random() * 150),
                        rewards: Math.random() > 0.5 ? Math.floor(Math.random() * 20 + 30) : 0,
                        isPortIn: Math.random() > 0.5,
                    });
                }
            }
        }
    }

    // Generate for previous month (to populate comparison)
    const prevMonth = new Date(today.getFullYear(), today.getMonth() - 1, 1);
    const daysInPrevMonth = new Date(prevMonth.getFullYear(), prevMonth.getMonth() + 1, 0).getDate();

     for (let i = 1; i <= daysInPrevMonth; i++) {
        if (new Date(prevMonth.getFullYear(), prevMonth.getMonth(), i).getDay() % 6 !== 0) {
            for (const rep of INITIAL_REPS) {
                 if (Math.random() > 0.3) { // Slightly different probability for variety
                    const date = new Date(prevMonth.getFullYear(), prevMonth.getMonth(), i).toISOString().split('T')[0];
                    entries.push({
                        id: `entry_prev_${rep.id}_${date}`,
                        repId: rep.id,
                        date: date,
                        activations: Math.random() > 0.6 ? (Math.random() > 0.8 ? 2 : 1) : 0,
                        vhi: Math.random() > 0.8 ? 1 : 0,
                        tablets: Math.random() > 0.85 ? 1 : 0,
                        protect: Math.random() > 0.7 ? 1 : 0,
                        accessories: Math.floor(Math.random() * 120),
                        rewards: Math.random() > 0.4 ? Math.floor(Math.random() * 20 + 30) : 0,
                        isPortIn: Math.random() > 0.5,
                    });
                }
            }
        }
    }
    return entries;
};

