const EditableAdminStat: React.FC<{
  value: number;
  onSave: (newValue: number) => void;
  isCurrency?: boolean;
}> = ({ value, onSave, isCurrency }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState(value.toString());

  useEffect(() => {
    if (!isEditing) {
      setEditValue(value.toString());
    }
  }, [value, isEditing]);

  const handleSave = () => {
    const numericValue = Number(editValue);
    if (!isNaN(numericValue) && numericValue !== value) {
      onSave(numericValue);
    }
    setIsEditing(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') handleSave();
    if (e.key === 'Escape') {
      setEditValue(value.toString());
      setIsEditing(false);
    }
  };

  if (isEditing) {
    return (
      <input
        type="number"
        value={editValue}
        onChange={(e) => setEditValue(e.target.value)}
        onBlur={handleSave}
        onKeyDown={handleKeyDown}
        autoFocus
        className="w-24 bg-gray-600 text-white text-center rounded-md py-1 px-2 border border-red-500 focus:outline-none focus:ring-1 focus:ring-red-500 text-base font-bold"
      />
    );
  }

  return (
    <span onClick={() => setIsEditing(true)} className="cursor-pointer hover:bg-gray-700/50 rounded-md px-2 py-1 transition-colors text-base font-bold">
      {isCurrency && '$'}{value.toLocaleString()}
    </span>
  );
};


