    }
  };

  return (
    <div className="flex h-screen bg-gray-900 text-white">
      <Sidebar 
        activeView={activeView} 
        setActiveView={setActiveView} 
      />
      <main className="flex-1 p-4 sm:p-6 lg:p-8 overflow-y-auto">
