import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import TeamDashboard from './components/Dashboard';
import QuickEntry from './components/Goals';
import TeamChat, { RepPerformance } from './components/Chat'; // Correctly import default and named components
import Promotions from './components/Promotions';
import Habits from './components/SalesLogModal';
import WeeklyReview from './components/SalesCoach';
import Admin from './components/Header';
import PracticeHub from './components/PracticeHub';
import ClientManager from './components/ClientManager';
import Comparisons from './components/Comparisons';
import DailyPulse from './components/DailyPulse';


import { useMockData } from './hooks/useMockData';

export type View = 'team-dashboard' | 'quick-entry' | 'reps' | 'promotions' | 'practice' | 'habits' | 'weekly-review' | 'team-chat' | 'admin' | 'client-manager' | 'comparisons' | 'daily-pulse';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<View>('team-dashboard');

  const mockData = useMockData();

  const renderView = () => {
    switch (activeView) {
      case 'team-dashboard':
        return <TeamDashboard data={mockData} />;
      case 'daily-pulse':
        return <DailyPulse data={mockData} />;
      case 'comparisons':
        return <Comparisons data={mockData} />;
      case 'quick-entry':
        return <QuickEntry reps={mockData.reps} addEntry={mockData.addEntry} />;
      case 'client-manager':
        return <ClientManager data={mockData} />;
      case 'reps':
        return <RepPerformance data={mockData} />;
      case 'promotions':
        return <Promotions promos={mockData.promos} />;
      case 'practice':
        return <PracticeHub promos={mockData.promos} />;
      case 'habits':
        return <Habits 
                  habits={mockData.habits} 
                  completedHabits={mockData.completedHabits} 
                  toggleHabit={mockData.toggleHabit} 
                />;
      case 'weekly-review':
        return <WeeklyReview />;
      case 'team-chat':
        return <TeamChat 
                  messages={mockData.chatMessages} 
                  reps={mockData.reps}
                  addMessage={mockData.addChatMessage}
                />;
      case 'admin':
        return <Admin 
                reps={mockData.reps}
                teamGoals={mockData.teamGoals}
                updateTeamGoals={mockData.setTeamGoals}
                addRep={mockData.addRep}
                removeRep={mockData.removeRep}
                promos={mockData.promos}
                addPromo={mockData.addPromo}
                updatePromo={mockData.updatePromo}
                removePromo={mockData.removePromo}
                displayProgress={mockData.displayProgress}
                adjustRepKpi={mockData.adjustRepKpi}
                timePeriod={mockData.timePeriod}
                setTimePeriod={mockData.setTimePeriod}
                salesPeriods={mockData.salesPeriods}
                addPeriod={mockData.addPeriod}
                updatePeriod={mockData.updatePeriod}
                removePeriod={mockData.removePeriod}
              />;
      default:
        return <TeamDashboard data={mockData} />;
    }
  };

  return (
    <div className="flex h-screen bg-gray-900 text-white">
      <Sidebar 
        activeView={activeView} 
        setActiveView={setActiveView} 
      />
      <main className="flex-1 p-4 sm:p-6 lg:p-8 overflow-y-auto">
        <div className="max-w-7xl mx-auto">
            {renderView()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import type { useMockData } from '../hooks/useMockData';
import type { PulseTimeSlot, KpiKey } from '../types';
import { QuickEntryIcon, FireIcon } from './icons';

interface DailyPulseProps {
    data: ReturnType<typeof useMockData>;
}

// Fix: Changed Record<Partial<KpiKey>, string> to Partial<Record<KpiKey, string>>
// to correctly indicate that only a subset of KPI keys are provided in this map.
const KPI_SHORT_LABELS: Partial<Record<KpiKey, string>> = {
    activations: 'ACT',
    vhi: 'VHI',
    tablets: 'TAB',
    protect: 'PRO',
};

const DailyPulse: React.FC<DailyPulseProps> = ({ data }) => {
    const { dailyPulse, updatePulseEntry, teamGoals } = data;
    const today = new Date().toISOString().split('T')[0];
    const todaysPulse = dailyPulse[today] || {};
    const slots: PulseTimeSlot[] = ['11am', '2pm', '5pm', '7pm'];

    const handleInputChange = (slot: PulseTimeSlot, kpi: KpiKey, value: string) => {
        const numValue = parseInt(value) || 0;
        updatePulseEntry(today, slot, { [kpi]: numValue });
    };

    const getDailyGoal = (kpi: KpiKey) => {
        // Simple approximation of daily goal from monthly
        return Math.ceil(teamGoals[kpi] / 24); 
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-white flex items-center gap-3">
                        <QuickEntryIcon className="h-6 w-6 text-red-500" />
                        Daily Workday Pulse
                    </h1>
                    <p className="text-sm text-gray-400">Track team momentum throughout the day at key intervals.</p>
                </div>
                <div className="flex gap-4">
                    <div className="bg-gray-800 px-4 py-2 rounded-lg border border-gray-700">
                        <p className="text-[10px] uppercase font-bold text-gray-500">Daily ACT Goal</p>
                        <p className="text-xl font-black text-white">{getDailyGoal('activations')}</p>
                    </div>
                    <div className="bg-gray-800 px-4 py-2 rounded-lg border border-gray-700">
                        <p className="text-[10px] uppercase font-bold text-gray-500">Daily VHI Goal</p>
                        <p className="text-xl font-black text-white">{getDailyGoal('vhi')}</p>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">
                {slots.map((slot) => {
                    const entry = todaysPulse[slot] || { activations: 0, vhi: 0, tablets: 0, protect: 0 };
                    const isFuture = false; // Add logic if needed to disable future slots

                    return (
                        <div key={slot} className="bg-gray-800 border border-gray-700 rounded-2xl overflow-hidden shadow-xl transition-all hover:border-red-500/50">
                            <div className="bg-gray-900/80 p-4 border-b border-gray-700 flex justify-between items-center">
                                <h3 className="text-lg font-black text-white uppercase tracking-tighter">{slot} Check-in</h3>
                                {entry.lastUpdated && (
                                    <span className="text-[10px] text-gray-500 font-mono">
                                        Updated {new Date(entry.lastUpdated).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                    </span>
                                )}
                            </div>

                            <div className="p-5 space-y-4">
                                {(Object.keys(KPI_SHORT_LABELS) as Array<keyof typeof KPI_SHORT_LABELS>).map(kpi => (
                                    <div key={kpi} className="flex items-center justify-between gap-4">
                                        <label className="text-xs font-bold text-gray-400 w-12">{KPI_SHORT_LABELS[kpi]}</label>
                                        <div className="flex-1">
                                            <input 
                                                type="number"
                                                min="0"
                                                value={entry[kpi] || 0}
                                                onChange={(e) => handleInputChange(slot, kpi, e.target.value)}
                                                className="w-full bg-gray-900 border border-gray-700 text-white font-bold rounded-lg px-3 py-2 focus:ring-2 focus:ring-red-500 focus:outline-none text-center tabular-nums"
                                            />
                                        </div>
                                    </div>
                                ))}
                            </div>

                            <div className="bg-gray-900/40 p-3 px-5 border-t border-gray-700 flex items-center justify-between">
                                <span className="text-[10px] font-bold text-gray-500 uppercase">Pacing Status</span>
                                <div className="flex items-center gap-2">
                                    {(entry.activations || 0) >= (getDailyGoal('activations') * 0.7) ? (
                                        <span className="text-[10px] font-bold text-green-400 flex items-center gap-1">
                                            <FireIcon className="w-3 h-3" /> ON TRACK
                                        </span>
                                    ) : (
                                        <span className="text-[10px] font-bold text-yellow-500">PUSH VOLUME</span>
                                    )}
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>

            <div className="bg-red-900/10 border border-red-900/30 p-6 rounded-2xl">
                <h2 className="text-lg font-bold text-white mb-4">Pulse Analysis</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 text-sm text-gray-300">
                    <p>
                        The Daily Pulse feed is designed to keep management and the team synchronized during peak retail hours. 
                        Entries made at 11am, 2pm, 5pm, and 7pm allow the team to pivot strategies if volume is low.
                    </p>
                    <div className="bg-gray-800/50 p-4 rounded-xl space-y-2">
                        <p className="font-bold text-white text-xs uppercase tracking-widest text-red-500">Coach Advice</p>
                        <p className="italic text-gray-400">
                            "If the 2pm pulse shows less than 3 activations, prioritize port-in pitches for the afternoon rush. 
                            Ensure every tablet demo is logged before the 5pm check-in."
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default DailyPulse;

import { GoogleGenAI } from "@google/genai";

// Initialize the Gemini client using a helper to ensure it's always fresh
const getAiClient = () => {
  if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
  }
  // Named parameter initialization as per guidelines
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const getSalesCoaching = async (prompt: string): Promise<string> => {
  try {
    const ai = getAiClient();
    // Use gemini-3-flash-preview for basic text tasks
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            {
              text: prompt,
            },
          ],
        },
      ],
      config: {
        systemInstruction: `You are an expert TOTAL WIRELESS by Verizon sales coach. Provide concise, actionable advice for TOTAL WIRELESS sales representatives. 
        Focus on product knowledge, sales techniques, and customer service. Use markdown for formatting, like lists or bold text, to make the information easy to digest.`,
      },
    });
    // .text is a property getter, not a method
    return response.text || "No coaching advice available at the moment.";
  } catch (error) {
    console.error("Error fetching from Gemini API:", error);
    if (error instanceof Error) {
        return `An error occurred while getting coaching advice: ${error.message}. Please check your API key and network connection.`;
    }
    return "An unknown error occurred while getting coaching advice.";
  }
};

export const getRolePlayFeedback = async (prompt: string, systemInstruction: string): Promise<string> => {
  try {
    const ai = getAiClient();
    // Use gemini-3-flash-preview for training simulations
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            {
              text: prompt,
            },
          ],
        },
      ],
      config: {
        systemInstruction: systemInstruction,
      },
    });
    // Use .text property to extract content
    return response.text || "No feedback generated for this session.";
  } catch (error) {
    console.error("Error fetching from Gemini API:", error);
    if (error instanceof Error) {
        return `An error occurred during the role-play session: ${error.message}. Please check your API key and network connection.`;
    }
    return "An unknown error occurred during the role-play session.";
  }
};
